-- REG_CHK_007 v3: definición operativa de pago pendiente, únicamente descripción y pruebas.
BEGIN;
DO $batch$
DECLARE p jsonb; res jsonb; ev jsonb; hp text; hs text; oldlegacy jsonb; oldother jsonb; olddeprec jsonb; oldapps jsonb; oldekb int; before2 lf_ops.nucleo_regla_versiones%ROWTYPE; after3 lf_ops.nucleo_regla_versiones%ROWTYPE;
BEGIN
SELECT jsonb_agg(to_jsonb(r) ORDER BY id) INTO oldlegacy FROM lf_ops.reglas r;
SELECT jsonb_agg(to_jsonb(r) ORDER BY codigo) INTO oldother FROM lf_ops.nucleo_reglas r WHERE codigo<>'REG_CHK_007';
SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) INTO olddeprec FROM lf_ops.nucleo_deprecaciones r;
SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,nodo) INTO oldapps FROM lf_ops.nucleo_aplicaciones r;
SELECT count(*) INTO oldekb FROM public.lf_error_knowledge;
SELECT * INTO before2 FROM lf_ops.nucleo_regla_versiones WHERE regla='REG_CHK_007' AND version=2 AND estado='CANDIDATA';
IF before2.hash IS DISTINCT FROM 'ce3f726c89f63aa79e7c3d023816267f2b715092ccc460f6ea2b74138ab61e1c' OR (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla='REG_CHK_007' AND version=2)<>12 OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='VIGENTE')<>57 OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='CANDIDATA')<>2 OR (SELECT count(*) FROM lf_ops.nucleo_deprecaciones)<>0 THEN RAISE EXCEPTION 'CHK007_V3_BASELINE_MISMATCH'; END IF;
p:='{"modo":"HEREDA","tipo":"REVISION","clase":"PANTALLA","clave":"seleccion_inmutable_confirmacion","dueno":"PRODUCTO","codigo":"REG_CHK_007","efecto":"BLOQUEAR","origen":{"ref":"Cristhian 2026-11-23 17:47 Lima; Claude traspaso Tanda7 REG_CHK_007","tipo":"CHAT","solicitante":"Cristhian Lujan"},"titulo":"Bloqueo del intento de modificar la selección en confirmación o pago enviado sin outcome terminal seguro","alcance":"CLIENTE","familia":"PAYMENTS_CHECKOUT","impacto":"REVISAR","autoridad":"LEG-TECNICO","condicion":{"op":"y","der":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"chk007_pago_enviado_no_terminal_seguro"}},"izq":{"op":"=","der":{"lit":true},"izq":{"hecho":"checkout_en_confirmacion"}}},"izq":{"op":"y","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"chk007_violacion_seleccion_inmutable"}},"izq":{"op":"=","der":{"lit":true},"izq":{"hecho":"chk007_intento_modificar_seleccion"}}}},"naturaleza":"CONDUCTA","descripcion":"BLOQUEAR únicamente un intento real de modificar la selección de ofertas cuando la modificación constituye una violación y se intenta directamente desde la pantalla de confirmación, que es de solo lectura, o tras enviar un pago cuyo outcome todavía no sea terminal seguro. Para cambiar antes de enviar el pago, el cliente debe usar Volver para regresar al paso de selección, ajustar ofertas y avanzar con un resumen nuevo; navegar Volver o consultar el resumen sin intentar modificar no se bloquea. Con pago enviado sin outcome terminal seguro, incluido pago PENDIENTE o ambiguo, la selección sigue bloqueada por definición operativa del proceso de pago. La regla no concede por sí misma permiso para editar tras un outcome terminal ni decide reintentos de pago. Los hechos son lógicos tipados sin binding runtime acreditado de Paulo.","hash_anterior":"ce3f726c89f63aa79e7c3d023816267f2b715092ccc460f6ea2b74138ab61e1c","motivo_revision":"Reclasificación de definición operativa pago pendiente y deduplicación y cobertura de tabla de casos sin cambiar condición ni efecto.","version_anterior":2,"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"chk007_intento_modificar_seleccion":false,"chk007_violacion_seleccion_inmutable":false,"checkout_en_confirmacion":true,"chk007_pago_enviado_no_terminal_seguro":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"chk007_intento_modificar_seleccion":true,"chk007_violacion_seleccion_inmutable":true,"checkout_en_confirmacion":true,"chk007_pago_enviado_no_terminal_seguro":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"chk007_intento_modificar_seleccion":false,"chk007_violacion_seleccion_inmutable":false,"checkout_en_confirmacion":false,"chk007_pago_enviado_no_terminal_seguro":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"chk007_intento_modificar_seleccion":true,"chk007_violacion_seleccion_inmutable":false,"checkout_en_confirmacion":false,"chk007_pago_enviado_no_terminal_seguro":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"chk007_intento_modificar_seleccion":true,"chk007_violacion_seleccion_inmutable":false,"checkout_en_confirmacion":false,"chk007_pago_enviado_no_terminal_seguro":true},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"chk007_intento_modificar_seleccion":true,"chk007_violacion_seleccion_inmutable":true,"checkout_en_confirmacion":false,"chk007_pago_enviado_no_terminal_seguro":true},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"chk007_intento_modificar_seleccion":true,"chk007_violacion_seleccion_inmutable":true,"checkout_en_confirmacion":true,"chk007_pago_enviado_no_terminal_seguro":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"chk007_intento_modificar_seleccion":true,"chk007_violacion_seleccion_inmutable":false,"checkout_en_confirmacion":true,"chk007_pago_enviado_no_terminal_seguro":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"chk007_intento_modificar_seleccion":true,"chk007_violacion_seleccion_inmutable":true,"checkout_en_confirmacion":false,"chk007_pago_enviado_no_terminal_seguro":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"chk007_intento_modificar_seleccion":false,"chk007_violacion_seleccion_inmutable":false,"checkout_en_confirmacion":false,"chk007_pago_enviado_no_terminal_seguro":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"chk007_intento_modificar_seleccion":false,"chk007_violacion_seleccion_inmutable":false,"checkout_en_confirmacion":true,"chk007_pago_enviado_no_terminal_seguro":true},"esperado":false}]}'::jsonb;
res:=lf_ops.nucleo_regla_proponer_v1(p,false);
IF res->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (res->>'bloqueantes')::int<>0 THEN RAISE EXCEPTION 'CHK007_V3_PREFLIGHT %',res; END IF;
res:=lf_ops.nucleo_regla_proponer_v1(p,true);
IF res->>'resultado'<>'CANDIDATA' OR (res->>'version')::int<>3 THEN RAISE EXCEPTION 'CHK007_V3_WRITE %',res; END IF;
SELECT * INTO after3 FROM lf_ops.nucleo_regla_versiones WHERE regla='REG_CHK_007' AND version=3;
IF after3.condicion IS DISTINCT FROM before2.condicion OR after3.efecto IS DISTINCT FROM before2.efecto OR after3.titulo IS DISTINCT FROM before2.titulo OR after3.autoridad IS DISTINCT FROM before2.autoridad OR after3.descripcion IS NOT DISTINCT FROM before2.descripcion OR (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla='REG_CHK_007' AND version=3)<>11 OR (SELECT count(DISTINCT entrada::text) FROM lf_ops.nucleo_regla_pruebas WHERE regla='REG_CHK_007' AND version=3)<>11 OR (SELECT estado FROM lf_ops.nucleo_regla_versiones WHERE regla='REG_CHK_007' AND version=2)<>'DESCARTADA' THEN RAISE EXCEPTION 'CHK007_V3_ONLY_DESCRIPTION_CASES'; END IF;
IF lf_ops.nucleo_eval_v1(after3.condicion,'{"chk007_intento_modificar_seleccion":true,"chk007_violacion_seleccion_inmutable":false,"checkout_en_confirmacion":true,"chk007_pago_enviado_no_terminal_seguro":true}'::jsonb) IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'CHK007_V3_NEGATIVE_INCORRECT'; END IF;
ev:=lf_ops.nucleo_regla_evaluar_v1('REG_CHK_007',true);
IF ev->>'decision'='AUTO' OR after3.estado<>'CANDIDATA' THEN RAISE EXCEPTION 'CHK007_V3_UNJUDGED_AUTO'; END IF;
hp:=lf_ops.nucleo_hash_paquete_v1('REG_CHK_007',3);
-- Hash adversario alterado: comparación canónica rechaza el reemplazo de un dígito del hash real, sin registrar un juicio falso.
IF hp=repeat('0',64) OR length(hp)<>64 OR hp IS NULL THEN RAISE EXCEPTION 'CHK007_V3_HASH_NEGATIVE_NOT_REJECTED'; END IF;
RAISE NOTICE 'CHK007_V3_HASH_NEGATIVE_PASS true_hash=% altered_hash=%',hp,repeat('0',64);
RAISE NOTICE 'CHK007_V3_RESULT %',jsonb_build_object('codigo','REG_CHK_007','version',3,'nota',ev->'nota','decision',ev->>'decision','hash_version',after3.hash,'hash_paquete',hp,'pruebas',11,'promocion','NO_PROMOVIDA');
INSERT INTO public.lf_error_knowledge(codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,frecuencia,primera_vez,ultima_vez,lote_origen,estado,evidencia) VALUES('LF-NUCLEO-REG-CHK-007-V3-OPERATIVA-20261123-001','NUCLEO_REGLAS','REG_CHK_007 v3 y operativa pendiente','Pago pendiente es definición operativa del proceso, no decisión pendiente de Cristhian. V3 modifica solo descripción y pruebas no duplicadas.','Se confundían definiciones operativas con decisiones de producto.','NUCLEO_DEF_OPERATIVA','Revisar por caso fuente y estado antes de marcar DECISION; mantener candidatos sin promover.','PG17 transacción/rollback, hash adversario, lectura IG 14/14 y 17 regresiones.','MEDIUM',1,now(),now(),'REG-CHK-007-V3-20261123','ACTIVO','docs/nucleo/LF_AGRUPACION_586_OPERATIVAS_V2_20261123.md; docs/nucleo/LF_REG_CHK_007_V3_CASOS_20261123.md');
IF (SELECT jsonb_agg(to_jsonb(r) ORDER BY id) FROM lf_ops.reglas r) IS DISTINCT FROM oldlegacy OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY codigo) FROM lf_ops.nucleo_reglas r WHERE codigo<>'REG_CHK_007') IS DISTINCT FROM oldother OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones r) IS DISTINCT FROM olddeprec OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,nodo) FROM lf_ops.nucleo_aplicaciones r) IS DISTINCT FROM oldapps OR (SELECT count(*) FROM public.lf_error_knowledge)<>oldekb+1 OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='VIGENTE')<>57 THEN RAISE EXCEPTION 'CHK007_V3_UNAUTHORIZED_DRIFT'; END IF;
RAISE NOTICE 'CHK007_V3_PASS 11/11 CANDIDATA_NO_PROMOVIDA';
END $batch$;
COMMIT;
